mapper.insert:
CREATE TABLE `${customerId}_inventories` ( `id` bigint(20) NOT NULL, `cycle_product_id` bigint(20) DEFAULT NULL, `cycle_product_detail_id` bigint(20) DEFAULT NULL, `sales_order_id` bigint(20) DEFAULT NULL, `point_of_sales_id` bigint(20) DEFAULT NULL, `credit_memo_id` bigint(20) DEFAULT NULL, `purchase_order_id` bigint(20) DEFAULT NULL, `purchase_return_id` bigint(20) DEFAULT NULL, `transfer_order_id` bigint(20) DEFAULT NULL, `type` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL, `customer_id` int(11) DEFAULT NULL, `vendor_id` int(11) DEFAULT NULL, `product_id` int(11) NOT NULL, `location_id` int(11) NOT NULL, `location_group_id` int(11) NOT NULL, `qty` int(11) NOT NULL, `unit_cost` decimal(15,3) NOT NULL, `date` date NOT NULL, `lots_number` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL, `date_expired` date NOT NULL, `created` datetime NOT NULL, `created_by` bigint(11) NOT NULL, `modified` datetime NOT NULL, `modified_by` bigint(11) NOT NULL, `is_active` tinyint(4) NOT NULL DEFAULT '1' ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
ALTER TABLE `${customerId}_inventories` ADD PRIMARY KEY (`id`), ADD KEY `product_id` (`product_id`), ADD KEY `location_id` (`location_id`), ADD KEY `lots_number` (`lots_number`), ADD KEY `location_group_id` (`location_group_id`);
ALTER TABLE `${customerId}_inventories` CHANGE `id` `id` BIGINT(20) NOT NULL AUTO_INCREMENT;

