SELECT id AS id, customer_code AS code, CONCAT(name_kh, ' (', `name`, ')') AS name FROM customers WHERE is_active = 1 AND `type` = 1
AND ( `name` LIKE CONCAT("%", #{filter.searchText}, "%") OR customer_code LIKE CONCAT("%", #{filter.searchText}, "%") )
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, NULL AS code, `name` AS name FROM location_groups WHERE is_active = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, `name` AS name FROM `groups` WHERE is_active = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, `name` AS name FROM module_types WHERE status = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT role_groups.id AS id, role_groups.`name` AS `name`, DATE_FORMAT(role_groups.created, '%d-%b-%y %h:%i') AS createdDate, DATE_FORMAT(role_groups.modified, '%d-%b-%y %h:%i') AS modifiedDate, CONCAT(users1.first_name, ' ', users1.last_name) AS createdBy, CONCAT(users2.first_name, ' ', users2.last_name) AS modifiedBy FROM `groups` AS role_groups LEFT JOIN users AS users1 ON users1.id = role_groups.created_by LEFT JOIN users AS users2 ON users2.id = role_groups.modified_by WHERE role_groups.is_active = 1 AND role_groups.name LIKE CONCAT("%", #{filter.searchText}, "%") ORDER BY
${filter.orderBy}
role_groups.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

